pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(bytes32 assertionId) public {
        // Record the policy before calling assertionDisputedCallback
        C.AssertionPolicy memory policyBefore = c.getAssertionPolicy(assertionId);
        // Call assertionDisputedCallback (this is the entry point that differs)
        // The call is expected to revert because msg.sender is not the optimisticAsserter,
        // but we only care about the state change to getAssertionPolicy.
        // To avoid revert, we need to call it from the optimisticAsserter address.
        // However, the contract is deployed with address(this) as the optimisticAsserter,
        // so calling via c will revert. We'll use try/catch.
        try c.assertionDisputedCallback(assertionId) {
            // succeeded
        } catch {
            // reverted - allowed
        }
        // Record the policy after the call
        C.AssertionPolicy memory policyAfter = c.getAssertionPolicy(assertionId);
        // The general rule: getAssertionPolicy should remain unchanged after calling assertionDisputedCallback
        assertTrue(
            policyAfter.blockAssertion == policyBefore.blockAssertion &&
            policyAfter.arbitrateViaEscalationManager == policyBefore.arbitrateViaEscalationManager &&
            policyAfter.discardOracle == policyBefore.discardOracle &&
            policyAfter.validateDisputers == policyBefore.validateDisputers
        );
    }
}

