pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(bytes32 assertionId) public {
        // Record the getAssertionPolicy result before the callback
        (bool beforeBlockAssertion, bool beforeArbitrateViaEscalationManager, bool beforeDiscardOracle, bool beforeValidateDisputers) = 
            abi.decode(abi.encode(c.getAssertionPolicy(assertionId)), (bool, bool, bool, bool));

        // Call assertionDisputedCallback (this test contract is the OptimisticAsserter, but msgsender is set via prank)
        vm.prank(address(c)); // Simulate the call coming from the contract itself (but any address works)
        c.assertionDisputedCallback(assertionId);

        // Record the getAssertionPolicy result after the callback
        (bool afterBlockAssertion, bool afterArbitrateViaEscalationManager, bool afterDiscardOracle, bool afterValidateDisputers) = 
            abi.decode(abi.encode(c.getAssertionPolicy(assertionId)), (bool, bool, bool, bool));

        // Assert that all fields remain unchanged
        assertTrue(
            beforeBlockAssertion == afterBlockAssertion &&
            beforeArbitrateViaEscalationManager == afterArbitrateViaEscalationManager &&
            beforeDiscardOracle == afterDiscardOracle &&
            beforeValidateDisputers == afterValidateDisputers,
            "getAssertionPolicy should not change after assertionDisputedCallback"
        );
    }
}

