pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(bytes32 assertionId) public {
        // Call assertionDisputedCallback to satisfy the driving entry point
        // This call will revert if msg.sender is not the optimisticAsserter
        // We expect it to revert since address(this) is not the underlying asserter
        // The rule is about getAssertionPolicy, which is called internally but we can observe via external call
        (bool success, ) = address(c).call(abi.encodeWithSelector(c.assertionDisputedCallback.selector, assertionId));
        // The call should revert because onlyOptimisticAsserter requires msg.sender == address(optimisticAsserter)
        assertTrue(!success, "assertionDisputedCallback should revert when called from non-asserter");

        // Now test the actual invariant: getAssertionPolicy always returns discardOracle = false
        C.AssertionPolicy memory policy = c.getAssertionPolicy(assertionId);
        assertTrue(!policy.discardOracle, "discardOracle must always be false");
    }
}

