pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(bytes32 assertionId) public {
        // The reference C reverts when called by anyone except the optimistic asserter.
        // The buggy version removes the check, so it never reverts.
        // Our rule: calling assertionDisputedCallback with a random caller should not revert.
        // But since the reference can revert, we must test that in the reference, only the asserter works.
        // To make the property hold for reference, we restrict the caller to be the asserter.
        vm.assume(msg.sender == address(c.optimisticAsserter()));
        // Actually, we want a general rule: the function should not revert when called by the asserter.
        // Fuzz over assertionId, but the caller is fixed to the asserter.
        // This property holds on reference (calls from asserter never revert) and fails on buggy (always reverts? No, buggy never reverts).
        // Wait, we need the rule to hold on reference and break on buggy.
        // For reference: calls from asserter never revert -> holds. Buggy: no revert regardless -> also holds. That doesn't break.
        // Rethink: The difference is that reference reverts for non-asserter, buggy doesn't. So the rule "always succeeds" fails on reference (non-asserter reverts).
        // To get a failing test on buggy, the rule must be something reference satisfies but buggy breaks.
        // The spec says: P.requestPrice() != M.requestPrice() after the call. requestPrice is a function? No, it's a function.
        // The difference is in state after call? But assertionDisputedCallback doesn't change state in reference (it's empty), in buggy it does nothing (same).
        // Actually the difference is that in reference, calling from non-asserter reverts, so no state change; in buggy, it doesn't revert, but still no state change.
        // The only difference in behavior is revert vs no revert. So the property should be about revert.
        // Let's define: calling assertionDisputedCallback with caller not equal to optimisticAsserter reverts on reference, not on buggy.
        // So the rule: the function does not revert when called by any address. That holds on buggy, fails on reference. So we need the opposite: it reverts when caller is not asserter. But that's not a general formula?
        // We can state: if caller != asserter then the call reverts. That holds on reference, breaks on buggy.
        vm.assume(msg.sender != address(c.optimisticAsserter()));
        // But we need to drive the call.
        // Use vm.prank to set caller, but the fuzz param should be the assertionId.
        // Actually, we can fuzz over a caller address and an assertionId.
        // But we already assumed msg.sender is not asserter. Then the call should revert on reference.
        // We'll capture revert.
        (bool success, ) = address(c).call(abi.encodeWithSelector(c.assertionDisputedCallback.selector, assertionId));
        assertTrue(!success, "Call did not revert but should have");
        // This rule holds on reference (non-asserter reverts) and fails on buggy (non-asserter does not revert, so success is true, assert fails).
    }
}

